def cases():
    return json.loads(json.dumps(CASES))

def mathematical(row):
    return likelihood.mathematical(row)

def production(row):
    return likelihood.production(row)

def native_query(row):
    return likelihood.native_query(row).replace('tol=1e-12','tol=1e-16')

def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=fixture['reference_code_sha256']:
        raise ValueError('Near-boundary reference source changed')
    if hashlib.sha256(Path(likelihood.__file__).read_bytes()).hexdigest()!=fixture['dependency_sha256']:
        raise ValueError('Independent likelihood reference source changed')
    if cases()!=[row['case'] for row in fixture['rows']]:raise ValueError('Near-boundary input definitions changed')
    queries=[{'key':row['key'],'code':native_query(row)} for row in cases()]
    if queries!=[{k:r[k] for k in q} for q,r in zip(queries,fixture['native']['rows'],strict=True)]:
        raise ValueError('Native near-boundary expressions changed')
    return fixture,queries

def execute(output):
    fixture,queries=check_identity()
    result=execute_queries(queries,output,name='mixed-near-boundary-gaussian-reference')
    for key in ['R','webR','wasm_sha256']:
        if result[key]!=fixture['native'][key]:raise ValueError('Near-boundary native runtime changed')
    return result
